async def sync_release_files(self):
    """ Purge + download files returning files removed + added """
    release_files = []

    for release in self.releases.values():
        release_files.extend(release)

    downloaded_files = set()
    deferred_exception = None
    tasks = []
    for release_file in release_files:
        tasks.append(self.download_file_async(release_file["url"], release_file["digests"]["sha256"]))

    results = await asyncio.gather(*tasks, return_exceptions=True)
    for i, result in enumerate(results):
        if isinstance(result, Exception):
            logger.exception(
                f"Continuing to next file after error downloading: "
                f"{release_files[i]['url']}"
            )
            if not deferred_exception:  # keep first exception
                deferred_exception = result
        else:
            downloaded_files.add(
                str(result.relative_to(self.mirror.homedir))
            )
    if deferred_exception:
        raise deferred_exception  # raise the exception after trying all files

    self.mirror.altered_packages[self.name] = downloaded_files

async def download_file_async(self, url, sha256sum):
    return await asyncio.to_thread(self.download_file, url, sha256sum)
